$MssDoubleDashScriptLicense$
delimiter ////
create function $lower DbSchemaName$.$sp_is_system_user$(
	argSecUserId varchar(36) )
returns boolean
not deterministic
begin
	declare retval boolean;
	declare varSecUserId varchar(36);
	declare done boolean default false;
	declare cur cursor for
		select
			susr.secuserid
		from $lower DbSchemaName$.SecUser as susr
		where
				susr.secuserid = argSecUserId
			and susr.login_id = 'system';
	declare continue handler for not found set done = true;
	select false into retval;
	open cur;
	read_loop: loop
		fetch cur into varSecUserId;
		if done then
			leave read_loop;
		end if;$CreateSPIsSystemUserLoopBody$
	end loop;
	close cur;
	return retval;
end;////
